import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.Dg5fKO7V.js";const u=JSON.parse('{"title":"Frontend Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"Architecture-Frontend.md","filePath":"Architecture-Frontend.md","lastUpdated":1788563284000}'),i={name:"Architecture-Frontend.md"};function o(r,e,d,c,l,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="frontend-architecture" tabindex="-1">Frontend Architecture <a class="header-anchor" href="#frontend-architecture" aria-label="Permalink to &quot;Frontend Architecture&quot;">​</a></h1><p>The frontend is SolidJS, TypeScript and Tailwind built by Vite under <code>src/</code>. Its structure is based on product features and explicit dependency direction.</p><h2 id="source-tree" tabindex="-1">Source tree <a class="header-anchor" href="#source-tree" aria-label="Permalink to &quot;Source tree&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span>|- app/                 boot, routes, global wiring and shell components</span></span>
<span class="line"><span>|- assets/              static data shipped as files</span></span>
<span class="line"><span>|- config/              timing, limit and layout tuning values</span></span>
<span class="line"><span>|- features/</span></span>
<span class="line"><span>|  |- anime/</span></span>
<span class="line"><span>|  |- command-palette/</span></span>
<span class="line"><span>|  |- connectivity/</span></span>
<span class="line"><span>|  |- discover/</span></span>
<span class="line"><span>|  |- downloads/</span></span>
<span class="line"><span>|  |- library/</span></span>
<span class="line"><span>|  |- player/</span></span>
<span class="line"><span>|  |- profile/</span></span>
<span class="line"><span>|  |- settings/</span></span>
<span class="line"><span>|  |- stats/</span></span>
<span class="line"><span>|  \`- watch/</span></span>
<span class="line"><span>|     |- ui/</span></span>
<span class="line"><span>|     |- io/</span></span>
<span class="line"><span>|     |- model/</span></span>
<span class="line"><span>|     \`- tests/</span></span>
<span class="line"><span>\`- shared/             named cross-feature capabilities</span></span></code></pre></div><p>Files do not sit loose in a feature root. Each module must reveal whether it renders, performs IO, models a decision or tests behaviour.</p><h2 id="feature-layers" tabindex="-1">Feature layers <a class="header-anchor" href="#feature-layers" aria-label="Permalink to &quot;Feature layers&quot;">​</a></h2><h3 id="ui" tabindex="-1"><code>ui/</code> <a class="header-anchor" href="#ui" aria-label="Permalink to &quot;\`ui/\`&quot;">​</a></h3><p>Solid components, JSX composition and rendering-specific behaviour. UI calls named operations from its feature&#39;s <code>io/</code> layer and consumes model types. It never imports <code>invoke</code> or the backend API directly. Component files use PascalCase and match the symbol they render.</p><h3 id="io" tabindex="-1"><code>io/</code> <a class="header-anchor" href="#io" aria-label="Permalink to &quot;\`io/\`&quot;">​</a></h3><p>Effectful feature orchestration: Solid resources, persistence, shared API calls, timers, media and platform lifecycles. Factory names start with an action that describes ownership, normally <code>create...</code> or <code>install...</code>. IO never imports UI.</p><h3 id="model" tabindex="-1"><code>model/</code> <a class="header-anchor" href="#model" aria-label="Permalink to &quot;\`model/\`&quot;">​</a></h3><p>Pure policy and transformations. Model code can be tested without a browser, backend, clock or network. It does not import feature IO, rendering, process-wide state or effectful shared packages.</p><h3 id="tests" tabindex="-1"><code>tests/</code> <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;\`tests/\`&quot;">​</a></h3><p>Tests are colocated with the feature they protect. Pure model tests and rendered interaction tests live together because both describe the same product capability.</p><h2 id="shared-capabilities" tabindex="-1">Shared capabilities <a class="header-anchor" href="#shared-capabilities" aria-label="Permalink to &quot;Shared capabilities&quot;">​</a></h2><p><code>src/shared</code> contains code with more than one real feature consumer. A folder names the capability, not an implementation layer.</p><table tabindex="0"><thead><tr><th>Package</th><th>Contract</th></tr></thead><tbody><tr><td><code>anime</code></td><td>Cross-feature anime card, episode and cache-key concepts</td></tr><tr><td><code>cache</code></td><td>Stale-while-revalidate resources and the cache they read</td></tr><tr><td><code>catalog</code></td><td>Catalogue warmup, refresh and the detail prefetch</td></tr><tr><td><code>colour</code></td><td>Colour parsing and derivation</td></tr><tr><td><code>easter-egg</code></td><td>The one hidden branch, kept where it can be found again</td></tr><tr><td><code>errors</code></td><td>Frontend error normalisation and reporting</td></tr><tr><td><code>formatting</code></td><td>Generic display formatting</td></tr><tr><td><code>i18n</code></td><td>Translation runtime, locale types and dictionaries</td></tr><tr><td><code>images</code></td><td>Cached image URLs, loading and prefetch</td></tr><tr><td><code>ipc</code></td><td>Typed Tauri command wrappers, the only frontend home of <code>invoke</code></td></tr><tr><td><code>keyboard</code></td><td>Shortcut parsing and keyboard coordination</td></tr><tr><td><code>logging</code></td><td>Scoped diagnostics, and webview failures forwarded to the application log</td></tr><tr><td><code>media</code></td><td>Shared media element and HLS behaviour</td></tr><tr><td><code>network</code></td><td>Reachability and latency state</td></tr><tr><td><code>notifications</code></td><td>Application notification state</td></tr><tr><td><code>platform</code></td><td>Frontend adapters for native integrations</td></tr><tr><td><code>preferences</code></td><td>Persisted preferences and active-profile state</td></tr><tr><td><code>providers</code></td><td>The provider registry the interface reads labels from</td></tr><tr><td><code>reactive</code></td><td>Small framework-level reactive utilities</td></tr><tr><td><code>track</code></td><td>Playback language and dub or sub policy</td></tr><tr><td><code>ui</code></td><td>Reusable visual primitives grouped by role</td></tr></tbody></table><p>Code is promoted to shared only after multiple features need the same contract. Sharing code merely because two implementations look similar creates coupling and is not a reason to move it here.</p><h2 id="application-shell" tabindex="-1">Application shell <a class="header-anchor" href="#application-shell" aria-label="Permalink to &quot;Application shell&quot;">​</a></h2><p><code>src/app/shell</code> holds layout that composes the whole application: sidebar, title bar, route error, offline gate and startup overlays. The app layer may import features. No feature and no shared package may import back into app.</p><h2 id="configuration-and-assets" tabindex="-1">Configuration and assets <a class="header-anchor" href="#configuration-and-assets" aria-label="Permalink to &quot;Configuration and assets&quot;">​</a></h2><p><code>src/config/timing.ts</code>, <code>limits.ts</code> and <code>layout.ts</code> own adjustable technical constants. Each value is named and documented with the reason for its size. Domain ids, locale keys and CSS classes stay with their owner. Only values that are genuinely tuned belong in config.</p><p>Large static datasets are assets rather than TypeScript modules. World-country geometry is stored in <code>src/assets/geo/world-countries.json</code> and validated by a schema-oriented test, which keeps generated data out of the code and coverage reports.</p><h2 id="solid-reactivity" tabindex="-1">Solid reactivity <a class="header-anchor" href="#solid-reactivity" aria-label="Permalink to &quot;Solid reactivity&quot;">​</a></h2><p>Components execute once and establish reactive computations. Do not flatten a reactive prop into a plain value:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> language</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> props.language        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// captured once</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> language</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> props.language  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// remains reactive</span></span></code></pre></div><p>The same applies to destructuring props. Preserve accessors until the value is actually consumed. Effects own cleanup for every listener, interval, media handler and process-wide subscription they install.</p><h2 id="naming" tabindex="-1">Naming <a class="header-anchor" href="#naming" aria-label="Permalink to &quot;Naming&quot;">​</a></h2><ul><li>Folders use kebab-case for multiword feature and capability names.</li><li>Components use PascalCase: <code>EpisodeTimeline.tsx</code>.</li><li>Other TypeScript files use camelCase: <code>episodePaging.ts</code>.</li><li>Factories name lifecycle: <code>createWatchPlaybackLifecycle.ts</code>.</li><li>A filename does not repeat its containing feature: <code>player/model/state.ts</code>, not <code>player/model/playerState.ts</code>.</li><li>Avoid structural names such as <code>helpers</code>, <code>utils</code>, <code>service</code>, <code>controller</code> or <code>component</code>.</li></ul><p>Architecture, naming, file headers and documentation are enforced by <code>eslint.config.js</code> and the repository-specific checks imported into Sonar. Run <code>npm run sonar:checks</code> to generate their issue report locally.</p>`,30)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
